S=/tmp/claude-1000/-home-vector-Desktop-Programming-EHLFinal2026/a11516cb-b9ab-4f94-b7ba-983b5e97b58f/scratchpad/inv; cat > $S/cases.py <<'E'
import sys, json; sys.path.insert(0, sys.argv[1])
from common import sessions
cases = {}; std = {}; opens = {}; outs={}
for kind in ("practice","sandbox"):
  for d in sessions(kind):
    cid = d["case"]["case_id"]
    cases.setdefault(cid, d["case"])
    for sid, th in d["threads"].items():
        std.setdefault(cid, {}).setdefault(sid, set()).add(json.dumps(th.get("standard_terms"), sort_keys=True))
    for sid, op in d["state"]["opening"].items():
        opens.setdefault(cid, {}).setdefault(sid, set()).add(json.dumps(op["terms"], sort_keys=True))
    o=d["outcome"]
    outs.setdefault(cid,set()).add((o["c_open"],o["c_best"],o.get("c_alt")))
for cid in sorted(cases):
    c = cases[cid]
    print("=====", cid, c["type"], c["title"])
    print(" negotiable", c["negotiable"]); print(" fixed", c["fixed_terms"]); print(" options", json.dumps(c["term_options"]))
    print(" buyer", json.dumps(c["buyer"])); print(" suppliers", c["suppliers"], "parts", c["parts"], "round_limit", c["round_limit"])
    for sid in std[cid]: print("  std", sid, std[cid][sid])
    for sid in opens[cid]: print("  open", sid, opens[cid][sid])
    print("  c_open,c_best,c_alt", outs[cid])
E
cd /home/vector/Desktop/Programming/EHLFinal2026/agent && uv run python $S/cases.py $S

