S=/tmp/claude-1000/-home-vector-Desktop-Programming-EHLFinal2026/a11516cb-b9ab-4f94-b7ba-983b5e97b58f/scratchpad/inv; cat > $S/relfit.py <<'E'
import sys, json, itertools, math; sys.path.insert(0, sys.argv[1])
from common import sessions
from arena_kit.cost import cost_breakdown, total_cost, score, closing_terms
cases={}; deals={}; outc={}
for kind in ("practice","sandbox"):
  for d in sessions(kind):
    c=d["case"]; cid=c["case_id"]; cases[cid]=c; o=d["outcome"]
    outc[cid]=(o["c_open"],o["c_best"])
    if o.get("deal"): deals.setdefault(cid,[]).append((d["_run"],d["_sid"],o))
def sup(cid, fc, r, spd=30):
    c=cases[cid]
    std={"payment_days":spd,"incoterm":c["fixed_terms"].get("incoterm","FCA"),"tooling_eur":0,"chargeback_eur_per_complaint":0}
    return {"standard":std,"interest_rate":r,"full_cost":fc}
def check(cid, fc, r):
    m=0
    for run,sid,o in deals[cid]:
        bd=cost_breakdown(cases[cid], o["terms"], supplier=sup(cid,fc,r))
        m=max(m,abs(bd["relationship"]-o["cost_breakdown"]["relationship"]))
    return m
# P01: least squares over fc, r
best=None
for r in [i/10000 for i in range(600,1400)]:
    # fc from 14-day deal
    for fc in [130.040+ j/1000 for j in range(-60,61)]:
        e=check("case:P01",fc,r)
        if best is None or e<best[0]: best=(e,fc,r)
print("P01 fit: max abs err EUR %.2f fc=%.3f r=%.4f"%best, "n deals", len(deals["case:P01"]))
# sensitivity: r range with err<5 EUR
ok=[(r,fc) for r in [i/10000 for i in range(600,1400)] for fc in [130.040+ j/1000 for j in range(-60,61)] if check("case:P01",fc,r)<5]
print(" P01 params with max err < 5 EUR: r %.4f..%.4f fc %.3f..%.3f"%(min(o[0] for o in ok),max(o[0] for o in ok),min(o[1] for o in ok),max(o[1] for o in ok)))
P01=(best[1],best[2])
# D01 at std 30: fc
best=None
for fc in [48.0+j/1000 for j in range(0,150)]:
    e=check("case:D01",fc,0.08)
    if best is None or e<best[0]: best=(e,fc)
print("D01 fit (r=0.08 assumed): err %.2f fc=%.3f"%best)
for r in [0.0,0.05,0.08,0.096,0.12,0.15,0.156,0.16,0.17,0.2]:
    print("   D01 r=%.3f max err %.2f"%(r,check("case:D01",best[1],r)))
D01fc=best[1]
# P02, P03: k90 fixed; fc = k90*(1-r/6)
K={"case:P02":371.6886,"case:P03":399.3602}
for cid,k in K.items():
    b=None
    for kk in [k+j/10000 for j in range(-300,301)]:
        e=check(cid,kk*(1-0.096/6),0.096)
        if b is None or e<b[0]: b=(e,kk)
    K[cid]=b[1]; print(cid,"k90 fit %.4f max err %.2f"%(b[1],b[0]))
SC={"case:P01":132.64,"case:P02":374.95,"case:P03":403.21,"case:P10":24.31}
print("P01 fc/should_cost", P01[0]/SC["case:P01"])
for cid,k in K.items():
    for r in (0.0,0.05,0.08,0.096,0.12):
        print(cid,"r=%.3f fc=%.2f ratio to should-cost %.4f"%(r,k*(1-r/6),k*(1-r/6)/SC[cid]))
# optimum
def optimum(cid, fc, r, lo, hi, restrict=None):
    c=cases[cid]; neg=[f for f in c["negotiable"] if f!="unit_price"]
    opts=[c["term_options"][f] for f in neg]
    best=None
    for combo in itertools.product(*opts):
        t=dict(zip(neg,combo))
        if restrict and not restrict(t): continue
        p=lo
        while p<=hi+1e-9:
            t["unit_price"]=round(p,2)
            C=total_cost(c,t,supplier=sup(cid,fc,r))
            if best is None or C<best[0]: best=(C,dict(t))
            p+=0.01
    return best
def show(cid,fc,r,lo,hi,label,restrict=None):
    C,t=optimum(cid,fc,r,lo,hi,restrict)
    co,cb=outc[cid]
    bd=cost_breakdown(cases[cid],t,supplier=sup(cid,fc,r))
    tt={k:(v if not isinstance(v,dict) else "clause db%s"%v["deadband_pct"]) for k,v in t.items()}
    print(f"{cid} {label}: r={r} fc={fc:.2f} min true C={C:.2f} at {tt} rel={bd['relationship']:.0f}; c_best={cb} diff(minC-c_best)={C-cb:.2f} score@min={score(co,C,cb):.3f}")
show("case:P01",P01[0],P01[1],120,140,"fit")
for pd in (14,30,45,60,90):
    show("case:P01",P01[0],P01[1],120,140,"pd=%d"%pd,lambda t,pd=pd:t["payment_days"]==pd)
for eff in cases["case:P01"]["term_options"]["effective_date"]:
    show("case:P01",P01[0],P01[1],120,140,"eff=%s"%eff,lambda t,eff=eff:t["effective_date"]==eff)
for r in (0.05,0.08,0.096,0.12):
    show("case:P02",K["case:P02"]*(1-r/6),r,340,380,"")
    show("case:P03",K["case:P03"]*(1-r/6),r,400,440,"")
for pd in (14,30,45,60,90):
    show("case:P02",K["case:P02"]*(1-0.096/6),0.096,340,380,"pd=%d"%pd,lambda t,pd=pd:t["payment_days"]==pd)
for pd in (14,30,45,60,90):
    show("case:P03",K["case:P03"]*(1-0.096/6),0.096,400,440,"pd=%d"%pd,lambda t,pd=pd:t["payment_days"]==pd)
for r in (0.05,0.08,0.096,0.12,0.156):
    show("case:D01",D01fc,r,46,53,"")
json.dump({"P01":P01,"D01fc":D01fc,"K":K},open(sys.argv[1]+"/fit.json","w"))
E
