    tt={k:(v if not isinstance(v,dict) else "clause db%s"%v["deadband_pct"]) for k,v in t.items()}
    print(f"{cid} {label}: r={r} fc={fc:.2f} min true C={C:.2f} at {tt} rel={bd['relationship']:.0f}; c_best={cb} diff(minC-c_best)={C-cb:.2f} score@min={score(co,C,cb):.3f}")
